/**
 * Cloudflare Worker entry: the OpenNext Next.js worker plus a cron trigger.
 *
 * The cron calls the app's own `/api/cron/tick` route with `CRON_SECRET`, so every piece of
 * workflow logic (full-auto approval, Buffer scheduling, publish tracking, integration health)
 * lives in the Next.js app and is shared with the manual "Run now" path and the local bridge.
 */
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type Env = { CRON_SECRET?: string; NEXT_PUBLIC_SITE_URL?: string };

const worker = {
  fetch: handler.fetch,

  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    if (!env.CRON_SECRET) return;
    const origin = env.NEXT_PUBLIC_SITE_URL || "https://content.internal";
    const request = new Request(`${origin}/api/cron/tick`, {
      method: "POST",
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(handler.fetch(request, env, ctx));
  },
};

export default worker;

// @ts-expect-error -- generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
